/ {
	soc {
		#address-cells = <1>;
		#size-cells = <1>;

		pinctrl: pinctrl {
			compatible = "zephyr,pinctrl-dummy";
			#pinctrl-cells = <1>;

			pinctrl_test_device_default: pinctrl_test_device_default {
				group0 {
					pinmux = <0x0>; /* Dummy pinmux value for pin 0 */
					bias-pull-up;
				};
				group1 {
					pinmux = <0x1>; /* Dummy pinmux value for pin 1 */
					bias-pull-down;
				};
				group2 {
					pinmux = <0x2>; /* Dummy pinmux value for pin 2 */
					bias-pull-up;
				};
				group3 {
					pinmux = <0x3>; /* Dummy pinmux value for pin 3 */
					bias-pull-down;
				};
				group4 {
					pinmux = <0x4>; /* Dummy pinmux value for pin 4 */
					bias-pull-up;
				};
				group5 {
					pinmux = <0x5>; /* Dummy pinmux value for pin 5 */
					bias-pull-down;
				};
				group6 {
					pinmux = <0x6>; /* Dummy pinmux value for pin 6 */
					bias-pull-up;
				};
				group7 {
					pinmux = <0x7>; /* Dummy pinmux value for pin 7 */
					bias-pull-down;
				};
			};

			pinctrl_test_device_sleep: pinctrl_test_device_sleep {
				group0 {
					pinmux = <0x8>; /* Dummy pinmux value for pin 0 in sleep state */
					bias-pull-down;
				};
			};
		};
	};

	test_device@0 {
		compatible = "vendor,test-device";
		reg = <0x0 0x4>; /* Base address 0x0, size 0x4. This fixes the error. */
		pinctrl-0 = <&pinctrl_test_device_default>;
		pinctrl-1 = <&pinctrl_test_device_sleep>;
		status = "okay";
	};
};
